#!/bin/bash
# Runs every test suite that exists and prints one normalized line per failure: "FAIL <suite>: <test name>".
# Used by tool/test_diff.sh. Backend: pytest (FastAPI). Frontend: vitest (Next.js).
set -uo pipefail
cd "$(dirname "$0")/.."
status=0
if [ -d backend ]; then
  (cd backend && HYPOTHESIS_PROFILE=ci uv run pytest -q --tb=short -rf) 2>&1 | tee /dev/stderr \
    | sed -nE 's/^FAILED ([^ ]+)( - .*)?$/FAIL backend: \1/p'
  [ "${PIPESTATUS[0]}" -ne 0 ] && status=1
fi
if [ -d frontend ] && [ -f frontend/package.json ]; then
  (cd frontend && npx vitest run) 2>&1 | tee /dev/stderr \
    | sed -nE 's/^ *(FAIL|×) +(.*[^ ])( [0-9]+ms)?$/FAIL frontend: \2/p'
  [ "${PIPESTATUS[0]}" -ne 0 ] && status=1
fi
exit $status
#!/bin/bash
# Only new failures count. Runs the test command, extracts failing test names with FAIL_PATTERN,
# and compares them with the baseline file (one name per line, committed).
#   tool/test_diff.sh                 compare
#   tool/test_diff.sh --update        rewrite the baseline (only on a reviewed main)
# Configure: TEST_CMD (default: tool/run_tests.sh, backend pytest + frontend vitest), FAIL_PATTERN (extended regex whose first capture group is the
# test name), BASELINE (default: tool/test_baseline.txt).
set -uo pipefail
cd "$(dirname "$0")/.."
TEST_CMD=${TEST_CMD:-tool/run_tests.sh 2>/dev/null}
FAIL_PATTERN=${FAIL_PATTERN:-'^FAIL (.*)$'}
BASELINE=${BASELINE:-tool/test_baseline.txt}
LOG=$(mktemp); NOW=$(mktemp)
bash -c "$TEST_CMD" > "$LOG" 2>&1
sed -nE "s/${FAIL_PATTERN}/\1/p" "$LOG" | sort -u > "$NOW"
if [ "${1:-}" = "--update" ]; then cp "$NOW" "$BASELINE"; echo "baseline: $(wc -l < "$BASELINE") failure(s)"; exit 0; fi
touch "$BASELINE"
NEW=$(comm -13 "$BASELINE" "$NOW"); FIXED=$(comm -23 "$BASELINE" "$NOW")
[ -n "$FIXED" ] && { echo "now passing (update the baseline):"; echo "$FIXED" | sed 's/^/  /'; }
if [ -n "$NEW" ]; then
  echo "NEW failures:"; echo "$NEW" | sed 's/^/  /'
  echo "Wall-clock benchmarks: rerun alone before counting them (explain the number)."
  exit 1
fi
echo "no new failures ($(wc -l < "$NOW") known)"
#!/usr/bin/env python3
"""Rule-registry lint. `python3 tool/review_lint.py` runs all rules; `... R01` runs one.

Add a rule: write a function returning a list of problems, decorate it with @rule('Rxx', 'what it checks').
Keep each rule tied to an incident in docs/review_rules.md.
"""
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
RULES = {}


def rule(rid, title):
    def wrap(fn):
        RULES[rid] = (title, fn)
        return fn
    return wrap


def tracked(*globs):
    out = subprocess.run(['git', 'ls-files', '--', *globs], cwd=ROOT, capture_output=True, text=True).stdout
    return [ROOT / p for p in out.splitlines() if p]


# Fill in the names you must never ship (machine names, user names, internal domains).
FORBIDDEN_NAMES = [r'\bDESKTOP-[A-Z0-9]{5,}\b', r'(?i)yongsheng', r'(?i)\bmacmini\b']
# Raw agent sessions must stay unedited (deliverable requirement); this file lists the patterns itself.
NAME_SCAN_EXCLUDE = ('prompt history/', 'tool/review_lint.py')


@rule('R01', 'No real host or user names in tracked files')
def no_real_names():
    problems = []
    for f in tracked():
        if not f.is_file() or str(f.relative_to(ROOT)).startswith(NAME_SCAN_EXCLUDE):
            continue
        text = f.read_text(errors='ignore')
        for pat in FORBIDDEN_NAMES:
            for m in re.finditer(pat, text):
                problems.append(f'{f.relative_to(ROOT)}: {m.group(0)}')
    return problems


@rule('R02', 'rm -rf only as rm -rf "${VAR:?}"')
def safe_rm():
    problems = []
    for f in tracked('*.sh', '**/*.sh'):
        for n, line in enumerate(f.read_text(errors='ignore').splitlines(), 1):
            if re.search(r'rm\s+-rf\s+"?\$(?!\{\w+:\?\})', line):
                problems.append(f'{f.relative_to(ROOT)}:{n}: {line.strip()}')
    return problems


def main(argv):
    selected = argv or sorted(RULES)
    failed = False
    for rid in selected:
